(5669778, 823779, 30049, '<td valign="top">Yeehaw!  Another splash shot.  :-/   Sorry, nothing personal, just getting worn on these a little.  I guess technically it fits the challenge seeing how a circle is a curved line.  Anyway...best of luck to you in the challenge.</td>', 'Yeehaw!  Another splash shot.  :-/   Sorry, nothing personal, just getting worn on these a little.  I guess technically it fits the challenge seeing how a circle is a curved line.  Anyway...best of luck to you in the challenge.', '2009-10-01 16:46:23.000000', NULL, 1),
(5669785, 824469, 30049, '<td valign="top">Well, I have to give you credit for a unique approach to a water drop shot.  It does look like a rose.  Good luck in the challenge.</td>', 'Well, I have to give you credit for a unique approach to a water drop shot.  It does look like a rose.  Good luck in the challenge.', '2009-10-01 16:48:10.000000', NULL, 1),
