INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5669937, 824668, 56797, '<td valign="top">*not voting as I''m in this challenge-just commenting since I''ve seen requests for comments in the challenge thread* <br/> <br/>Very nicely composed. I like the idea and the colors. The drawbacks for me are the grey tones in the upper right hand side of the BG as well as the sensor dust/dirt up there and the fact that the balls aren''t smooth. At first glance they look like metal balls but upon closer inspection are obviously beads with holes through them. Seeing some of the holes and the plastic texture take away from the sleek beauty of the shot. Otherwise very nice though.</td>', '*not voting as I''m in this challenge-just commenting since I''ve seen requests for comments in the challenge thread*  Very nicely composed. I like the idea and the colors. The drawbacks for me are the grey tones in the upper right hand side of the BG as well as the sensor dust/dirt up there and the fact that the balls aren''t smooth. At first glance they look like metal balls but upon closer inspection are obviously beads with holes through them. Seeing some of the holes and the plastic texture take away from the sleek beauty of the shot. Otherwise very nice though.', '2009-10-01 17:55:30.000000', NULL, 1),
(5669939, 824428, 56797, '<td valign="top">*not voting as I''m in this challenge-just commenting since I''ve seen requests for comments in the challenge thread* <br/> <br/>It''s cool that you''ve caught such a large scene in a tiny little reflection. Very well done. The colors are pretty cool too. The only drawbacks are hte dirt around the base of the silver thing(whatever it is) and on the object itself. <br/> <br/>HTH</td>', '*not voting as I''m in this challenge-just commenting since I''ve seen requests for comments in the challenge thread*  It''s cool that you''ve caught such a large scene in a tiny little reflection. Very well done. The colors are pretty cool too. The only drawbacks are hte dirt around the base of the silver thing(whatever it is) and on the object itself.  HTH', '2009-10-01 17:56:59.000000', NULL, 1),
(5669943, 823799, 56797, '<td valign="top">*not voting as I''m in this challenge-just commenting since I''ve seen requests for comments in the challenge thread* <br/> <br/>Wow! This is pretty cool. Love the colors. Looks like the main focus was on the rim of the blue container instead of the eyes of the animal. That takes somethign away from this for me. But otherwise very cool.</td>', '*not voting as I''m in this challenge-just commenting since I''ve seen requests for comments in the challenge thread*  Wow! This is pretty cool. Love the colors. Looks like the main focus was on the rim of the blue container instead of the eyes of the animal. That takes somethign away from this for me. But otherwise very cool.', '2009-10-01 17:58:12.000000', NULL, 1),
