(5674857, 824259, 83313, '<td valign="top">Nice use of the shadows to add depth and interest. Headboard on a bed?</td>', 'Nice use of the shadows to add depth and interest. Headboard on a bed?', '2009-10-04 21:38:51.000000', NULL, 1),
(5674865, 823773, 83313, '<td valign="top">Great. Now I''m gonna have the <a href="//www.amazon.com/s/ref=nb_ss_0_9?url=search-alias%3Ddigital-music&amp;field-keywords=wolf+creek+pass&amp;x=0&amp;y=0&amp;sprefix=wolf+cree" rel="nofollow" target="_blank">C.W. McCall song of the same name</a> stuck in my head the rest of the evening.</td>', 'Great. Now I''m gonna have the C.W. McCall song of the same name stuck in my head the rest of the evening.', '2009-10-04 21:45:55.000000', NULL, 1),
(5674867, 823657, 83313, '<td valign="top">An interesting looking abstract that could be a number of different things that get statistics quoted about them. From the blurred reflection, most likely an auto accident.</td>', 'An interesting looking abstract that could be a number of different things that get statistics quoted about them. From the blurred reflection, most likely an auto accident.', '2009-10-04 21:47:54.000000', NULL, 1),
